-- Generated by scripts/build-name-policy-migration.py from lib/public-name-policy.json.
-- Validates only public display names, never email addresses or authorization metadata.
begin;
create or replace function public.community_name_allowed(value text)
returns boolean language sql immutable parallel safe security invoker set search_path='' as $policy$
 with original as (
  select lower(normalize(coalesce(value,''),NFKD)) as name
 ), folded as (
  select name, regexp_replace(translate(name,'аеорсухіјѕӏнкмтαοικντυχερłøđ','aeopcyxijslhkmtaoikvtuxeplod'),'[̀-ͯ]','','g') as text from original
 ), forms as (
  select name, regexp_replace(translate(text,'0134578','oieastb'),'[^a-z]','','g') as compact,
  regexp_split_to_array(regexp_replace(text,'[^a-z]+',' ','g'),' +') as words from folded
 )
 select coalesce(char_length(btrim(value)) between 2 and 60 and value ~ '[[:alnum:]]'
  and not exists(select 1 from unnest(array['nichiren','nichikan','nichimoku','nissho','nichiro','nitcho','nichiji','nikko','buddha','buddh','budda','buddismo','buddita','bodhisatt','bodhisat','bodisat','loto','lotus','daimoku','gongyo','gohonzon','honzon','gosho','sutra','sutta','myoho','renge','nammyo','namumyo','kosenrufu','ichinen','sanzen','sangha','dharma','karma','nirvana','shakyamuni','sakyamuni','siddhartha','gautama','tathagata','amida','amitabha','maitreya','manjushri','manjusri','samantabhadra','fugen','monju','avalokitesvara','avalokiteshvara','kanzeon','kannon','guanyin','jizo','ksitigarbha','jogyo','jyogyo','muhengyo','anryugyo','visistacaritra','anantacaritra','soka','gakkai','makiguchi','ikeda','tientai','tendai','zhiyi','risshoankoku','juzu','shodai','mandala','daishonin','shonin','shoshu','shakubuku','kosen','shohondo','shotenzenjin','niten','gatten','taho','hoben','juryo','honmon','mantra','dharani','samadhi','namaste']::text[]) term where strpos(compact,term)>0)
  and not exists(select 1 from unnest(array['zen','nam','namu','kyo','toda']::text[]) term where term=any(words) or compact=term)
  and not exists(select 1 from unnest(array['日蓮','仏','佛','菩薩','法華','南無','妙法','蓮華','蓮','御本尊','題目','勤行','釈迦','地蔵','観音','文殊','普賢','弥勒']::text[]) term where strpos(name,normalize(term,NFKD))>0),false)
 from forms;
$policy$;
revoke all on function public.community_name_allowed(text) from public,anon;
grant execute on function public.community_name_allowed(text) to authenticated,service_role;
-- The existing signup trigger creates a profile in the same transaction. A forbidden
-- profile name therefore rejects both direct signups and later profile/API updates.
alter table public.profiles add constraint community_public_name_policy check(public.community_name_allowed(display_name));
commit;
